// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
bool has_file_open( const std::string & fd_dir, const struct stat & target )
{
    DIR * dir = ::opendir( fd_dir.c_str() );

    if( !dir ) {
        return false;   // process gone or not visible (other user)
    }

    bool found = false;

    while( struct dirent * entry = ::readdir( dir ) ) {
        if( entry->d_name[0] == '.' ) {
            continue;
        }

        struct stat st;
        const std::string path = fd_dir + "/" + entry->d_name;

        if( ::stat( path.c_str(), &st ) != 0 ) {
            continue;   // fd closed meanwhile
        }

        if( st.st_dev == target.st_dev && st.st_ino == target.st_ino ) {
            found = true;
            break;
        }
    }

    ::closedir( dir );
    return found;
}
