// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
std::vector<pid_t> processes_using_file( const std::string & file )
{
    std::vector<pid_t> pids;

    struct stat target;

    if( ::stat( file.c_str(), &target ) != 0 ) {
        return pids;    // file does not exist (yet) -> nobody can hold it
    }

    DIR * proc = ::opendir( "/proc" );

    if( !proc ) {
        DEBUG( Tools::format( "cannot read /proc: %s", std::strerror( errno ) ) );
        return pids;
    }

    const pid_t self = ::getpid();

    while( struct dirent * entry = ::readdir( proc ) ) {
        if( !is_number( entry->d_name ) ) {
            continue;
        }

        const pid_t pid = (pid_t)std::atoi( entry->d_name );

        if( pid == self ) {
            continue;
        }

        if( has_file_open( "/proc/" + std::string( entry->d_name ) + "/fd", target ) ) {
            pids.push_back( pid );
        }
    }

    ::closedir( proc );

    return pids;
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
bool wait_until_file_is_free( const std::string & file,
                              int poll_interval_ms,
                              int timeout_s,
                              std::vector<pid_t> * holders )
{
    const int interval = poll_interval_ms > 0 ? poll_interval_ms : 1000;

    const auto begin = std::chrono::steady_clock::now();

    for( ;; ) {
        std::vector<pid_t> pids = processes_using_file( file );

        if( holders ) {
            *holders = pids;
        }

        if( pids.empty() ) {
            return true;
        }

        const auto now = std::chrono::steady_clock::now();
        const long elapsed_s =
            (long)std::chrono::duration_cast<std::chrono::seconds>( now - begin ).count();

        if( timeout_s > 0 && elapsed_s >= timeout_s ) {
            DEBUG( Tools::format( "%s is still open after %ld s - giving up",
                                  file.c_str(), elapsed_s ) );
            return false;
        }

        DEBUG( Tools::format( "%s is open (pid %ld) - waiting",
                              file.c_str(), (long)pids.front() ) );

        std::this_thread::sleep_for( std::chrono::milliseconds( interval ) );
    }
}
